import{_ as e,o as a,a as i,b as n}from"./app.BGziXukh.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/technical_appendix"},{"text":"浮点计算","link":"/guide/technical_appendix/floating_point_computation/floating_point_computation"},{"text":"概述","link":"/guide/technical_appendix/floating_point_computation/overview"}]},"headers":[],"relativePath":"guide/technical_appendix/floating_point_computation/overview.md","filePath":"guide/technical_appendix/floating_point_computation/overview.md","outlineHeaders":[{"level":2,"title":"章节组织","slug":"章节组织","link":"#章节组织"},{"level":2,"title":"阅读建议","slug":"阅读建议","link":"#阅读建议"}],"lastUpdated":1794984466000}'),o={name:"guide/technical_appendix/floating_point_computation/overview.md"};function l(_,t,r,c,d,p){return a(),i("div",null,[...t[0]||(t[0]=[n('<div><article class="markdown-body"><h1>概述</h1><p>本文介绍浮点计算在Ascend C中的基本性质、数据类型与运算行为，帮助开发者理解浮点运算的精度特性，在保证精度的前提下充分发挥硬件性能。浮点数只能近似表示实数，相同的运算在不同实现（硬件、计算顺序）下可能产生不同的结果；理解这些特性是编写正确且高性能浮点算子的基础。</p><h2 id="章节组织">章节组织<a class="header-anchor" href="#章节组织">​</a></h2><ul><li><strong><a href="./floating_point_basics.html">浮点计算基础</a></strong>：浮点数的IEEE-754编码格式、规格数与非规格数、特殊值、结合律与运算顺序、乘加融合、饱和与溢出处理以及舍入模式。</li><li><strong><a href="./ascendc_data_type_summary.html">Ascend C数据类型汇总</a></strong>：Ascend C支持的各浮点数据类型的类型总览、数据范围与精度属性，以及FP8与FP4浮点数格式（含MX缩放计算）、hifloat数据格式、HF计算模式等低精度与高性能浮点特性。</li><li><strong><a href="./floating_point_operation.html">浮点操作</a></strong>：按API与编程范式介绍浮点数参与的运算，包括Reg矢量计算、SIMT运算与Cube运算的浮点相关接口及浮点行为差异。</li></ul><h2 id="阅读建议">阅读建议<a class="header-anchor" href="#阅读建议">​</a></h2><ul><li>初次接触浮点精度问题的开发者，建议从<a href="./floating_point_basics.html">浮点计算基础</a>读起，重点理解舍入模式、饱和与溢出处理对数值结果的影响。</li><li>关心具体数据类型的取值范围、编码方式与转换规则的开发者，可直接查阅<a href="./ascendc_data_type_summary.html">Ascend C数据类型汇总</a>中对应的数据类型小节。</li><li>需要了解某一类运算（矢量计算、SIMT运算、矩阵计算）的浮点行为与可用接口的开发者，可查阅<a href="./floating_point_operation.html">浮点操作</a>中对应的运算小节。</li></ul></article></div>',1)])])}const g=e(o,[["render",l]]);export{h as __pageData,g as default};
